import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run([str(fz), 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

def find_message(payload, needle):
    return next(item for item in payload['items'] if needle in item['message'])

branch_divergence = verify('branch_divergence', '''
    fn main() -> i32 {
        let p = alloc(32)
        if true {
            free(p)
        } else {
        }
        close(p)
        return 0
    }
''', 1)
branch_diag = find_message(branch_divergence, 'divergent ownership state for `p`')
assert 'every branch and loop path' in (branch_diag.get('help') or ''), branch_diag
assert any('consumes non-owned or already-consumed value `p`' in message or 'uses moved value `p` after move/consume' in message or 'conditionally consumed value `p`' in message for message in messages(branch_divergence)), branch_divergence

continue_reuse = verify('continue_reuse', '''
    fn main() -> i32 {
        let i: i32 = 0
        let p = alloc(32)
        while i < 2 {
            if i == 0 {
                free(p)
                i = i + 1
                continue
            }
            close(p)
            i = i + 1
        }
        return 0
    }
''', 1)
continue_diag = find_message(continue_reuse, 'conditionally consumed value `p`')
assert 'every branch and loop path' in (continue_diag.get('help') or ''), continue_diag

break_cleanup = verify('break_cleanup', '''
    fn main() -> i32 {
        let p = alloc(32)
        while true {
            free(p)
            break
        }
        return 0
    }
''', 0)
assert break_cleanup['errors'] == 0, break_cleanup
assert not any('leaks allocation' in message or 'divergent ownership state for `p`' in message or 'conditionally consumed value `p`' in message for message in messages(break_cleanup)), break_cleanup

loop_local_cleanup = verify('loop_local_cleanup', '''
    fn main() -> i32 {
        let i: i32 = 0
        while i < 2 {
            let p = alloc(32)
            free(p)
            i = i + 1
        }
        return 0
    }
''', 0)
assert loop_local_cleanup['errors'] == 0, loop_local_cleanup
assert not any('divergent ownership state' in message or 'conditionally consumed value' in message for message in messages(loop_local_cleanup)), loop_local_cleanup

print('compiler-memory-control-flow-merges-ok')

